class Whycodes < Formula
  desc "Terminal coding agent written in Rust"
  homepage "https://why.codes"
  version "0.6.1"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/whycorporation/whycodes/releases/download/v0.6.1/whycodes-aarch64-apple-darwin.tar.gz"
      sha256 "89ae534daa77103297195199a6e9bcbc5cc3dc8fde5514caa87f49cb1ab9f955"
    end

    on_intel do
